script:
(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const arm = () => {
        document.documentElement.classList.add("sp-js");
        const io = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                if (!entry.isIntersecting) continue;
                entry.target.classList.add("sp-in");
                io.unobserve(entry.target);
            }
        }, { threshold: 0.08, rootMargin: "0px 0px -6% 0px" });
        document.querySelectorAll(".sp-rise").forEach((el) => io.observe(el));

        let i = 0;
        const cio = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                if (!entry.isIntersecting) continue;
                const el = entry.target;
                el.style.transitionDelay = ((i++ % 9) * 70) + "ms";
                el.classList.add("sp-in");
                cio.unobserve(el);
            }
        }, { threshold: 0.4 });
        document.querySelectorAll(".sp-check").forEach((el) =>
            cio.observe(el));
    };
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", arm);
    } else {
        arm();
    }
})();
